import type { GeneratedDoc } from "fumadocs-typescript";
import { getTypeTableKey, type TypeTableQuery } from "@/lib/type-table-key";
import typeTables from "@/registry/__type-tables__.json";

export { componentPropTag } from "@/lib/type-table-key";

const generatedTypeTables = typeTables as Record<string, GeneratedDoc[]>;

/**
 * Type tables are generated by scripts/build-registry.mts so the Worker never
 * bundles fumadocs-typescript / the TypeScript compiler.
 */
export function getTypeTable(query: TypeTableQuery): GeneratedDoc[] {
	const docs = generatedTypeTables[getTypeTableKey(query)];
	if (!docs) {
		throw new Error(
			`Type table was not generated for ${JSON.stringify(query)}. Run \`pnpm registry:build\`.`,
		);
	}
	return docs;
}
